const DEFAULT_PRECISION: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let sign = if value.is_sign_negative() { "-" } else { "" };
    let magnitude = f64::from(value.abs());

    // Match iostream defaultfloat behavior: 6 significant digits, fixed within
    // the default exponent window and scientific notation otherwise.
    let scientific = format!("{:.*e}", DEFAULT_PRECISION - 1, magnitude);
    let (mantissa, exponent) = split_scientific(&scientific);

    if exponent < -4 || exponent >= DEFAULT_PRECISION as i32 {
        let trimmed = trim_fraction(mantissa);
        return format!("{sign}{trimmed}{}", format_exponent(exponent));
    }

    let fractional_digits = (DEFAULT_PRECISION as i32 - exponent - 1).max(0) as usize;
    let fixed = format!("{:.*}", fractional_digits, magnitude);
    let trimmed = trim_fraction(&fixed);
    format!("{sign}{trimmed}")
}

fn split_scientific(value: &str) -> (&str, i32) {
    let index = value.find('e').expect("scientific notation");
    let mantissa = &value[..index];
    let exponent = value[index + 1..].parse::<i32>().expect("valid exponent");
    (mantissa, exponent)
}

fn trim_fraction(value: &str) -> String {
    if !value.contains('.') {
        return value.to_string();
    }

    let trimmed = value.trim_end_matches('0').trim_end_matches('.');
    if trimmed.is_empty() {
        String::from("0")
    } else {
        trimmed.to_string()
    }
}

fn format_exponent(exponent: i32) -> String {
    let sign = if exponent < 0 { '-' } else { '+' };
    format!("e{}{abs:02}", sign, abs = exponent.abs())
}

